export const SNAPSHOT="2026-10-06";
export const weights:Record<string,number>={"Weekly work":25,"Concept checks":15,"Essays":35,"Final project":25};
export function grade(c:Course){let earned=0,weight=0;for(const [g,w] of Object.entries(weights)){const a=c.assignments.filter(a=>a.group===g&&a.score!==null);if(a.length){earned+=w*a.reduce((s,a)=>s+(a.score||0),0)/a.reduce((s,a)=>s+a.points,0);weight+=w;}}return earned/weight*100;}
export function letter(n:number){return n>=97?"A+":n>=93?"A":n>=90?"A−":n>=87?"B+":n>=83?"B":n>=80?"B−":n>=70?"C":n>=60?"D":"F";}
